window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-28301\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 527 na letra ν · nº geral 28301</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inteligência; razão; pensamento: θᾶττον νοήματος κατέδραμε longo correu mais rápido que o pensamento 2 aquilo que se pensa; reflexão; pensamento 3 intenção; desígnio; propósito 4 idéia; achado 5 Fil. idéia; conceito. 〈νοέω〉</p></section></article>\n<article id=\"entry-dgp-28302\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοήμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 528 na letra ν · nº geral 28302</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 inteligente; reflexivo; sensato; de bom senso ♦ Νοήμων 2 Noemão, n. de h. 〈νοέω〉</p></section></article>\n<article id=\"entry-dgp-28303\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 529 na letra ν · nº geral 28303</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o pensar 2 faculdade de pensar; intelecto; inteligência 3 idéia; conceito. 〈νοέω〉</p></section></article>\n<article id=\"entry-dgp-28304\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 530 na letra ν · nº geral 28304</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inteligente; sensato 2 captado pela inteligência; inteligível. 〈νοέω〉</p></section></article>\n<article id=\"entry-dgp-28305\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοθαγενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 531 na letra ν · nº geral 28305</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de nascimento ilegítimo; bastardo. 〈νό­θος, γένος〉</p></section></article>\n<article id=\"entry-dgp-28306\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοθεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 532 na letra ν · nº geral 28306</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nascimento ilegítimo, espúrio; descendência bastarda. 〈νόθος〉</p></section></article>\n<article id=\"entry-dgp-28307\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοθεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 533 na letra ν · nº geral 28307</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 corromper; adulterar; danificar 2 considerar espúrio. 〈νόθος〉</p></section></article>\n<article id=\"entry-dgp-28308\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόθος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 534 na letra ν · nº geral 28308</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bastardo; ilegítimo 2 alterado; corrompido; falso; não autêntico.</p></section></article>\n<article id=\"entry-dgp-28309\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νομαδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 535 na letra ν · nº geral 28309</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Numídia, país da África.</p></section></article>\n<article id=\"entry-dgp-28310\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νομαδικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 536 na letra ν · nº geral 28310</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Numídia. 〈Νομαδία〉</p></section></article>\n<article id=\"entry-dgp-28311\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόμαιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 537 na letra ν · nº geral 28311</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 concordante com o uso; habitual ♦ τὰ νόμαια 2 usos; costumes. 〈νόμος〉</p></section></article>\n<article id=\"entry-dgp-28312\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 538 na letra ν · nº geral 28312</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que concerne aos pastores ou aos rebanhos. 〈νομή〉</p></section></article>\n<article id=\"entry-dgp-28313\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομάρχης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 539 na letra ν · nº geral 28313</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 nomarca, chefe de um nomo no Egito 2 governador de uma província ou de uma região. 〈νόμος, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-28314\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 540 na letra ν · nº geral 28314</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 que vagueia em busca de pastagem; que pasta (cavalo) 2 que vagueia como os rebanhos; nômade (pessoa). 〈νέμω〉</p></section></article>\n<article id=\"entry-dgp-28315\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νομάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 541 na letra ν · nº geral 28315</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 da Numídia; númida ♦ οἱ Νομάδες 2 os númidas.</p></section></article>\n<article id=\"entry-dgp-28316\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νομᾶς, ᾶ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 542 na letra ν · nº geral 28316</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Numa, rei de Roma. [lat.]</p></section></article>\n<article id=\"entry-dgp-28317\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόμευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 543 na letra ν · nº geral 28317</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rebanho. 〈νομεύω〉</p></section></article>\n<article id=\"entry-dgp-28318\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 544 na letra ν · nº geral 28318</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que destina a cada um a sua parte; distribuidor 2 pastor 3 pl. traves do arcabouço de um navio; costado. 〈νέμω〉</p></section></article>\n<article id=\"entry-dgp-28319\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομευτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 545 na letra ν · nº geral 28319</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de pastor; pastoril 2 hábil para fazer pastar. 〈νομεύω〉</p></section></article>\n<article id=\"entry-dgp-28320\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 546 na letra ν · nº geral 28320</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 intr. ser pastor 2 levar à pastagem; apascentar 3 dirigir ♦ méd. pas. 4 pastar. 〈νομή〉</p></section></article>\n<article id=\"entry-dgp-28321\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 547 na letra ν · nº geral 28321</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 distribuição; repartição; partilha 2 resultado de partilha; herança 3 lugar de pastagem; pastagem; pasto 4 ação de pastar ou de se alimentar 5 ação de devorar, de corroer 6 forragem; pasto 7 pl. donativo, em Roma, gratificação dada pelo imperador aos soldados. 〈νέμω〉</p></section></article>\n<article id=\"entry-dgp-28322\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νομήτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 548 na letra ν · nº geral 28322</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Numitor, avô de Rômulo e Remo. [lat.]</p></section></article>\n<article id=\"entry-dgp-28323\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 549 na letra ν · nº geral 28323</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. νομίσω, át. νομιῶ, aor. ἐνόμισα, perf. νενό­μικα) ativa 1 fazer uso de; praticar habitualmente; ter o costume de, ac. ou dat. 2 cultuar (deus); reconhecer; honrar 3 adotar um uso; introduzir um costume; tomar emprestado um hábito, ac., de, ἀπό, παρά e gen. 4 considerar como; ver como, ac. e predic. no ac. 5 pensar; crer; considerar que, or. inf., or. conj. (ὡς) rar. part. PASSIVa 6 ser habitual; ser em conformidade com o costume 7 passar por; ser visto como 8 ser considerado propriedade de; passar por pertencer a, gen. 1 φωνῇ νομίζουσι Σκυθικῇ her. eles se servem habitualmente da língua cita, ἀγῶσι καὶ θυσίαις διετησίοις νομίζουσι tuc. eles costumam realizar concursos e sacrifícios durante o ano todo, ἐν δὲ Λακεδαίμονι σιδήρῳ σταθμῷ νομίζουσι plat. na Lacedemônia eles usam o ferro como moeda, νομίζουσι ∆ιῒ θυσίας ἔρδειν her. têm o costume de oferecer sacrifícios a Zeus 2 ἀδικεῖ Σωκράτης οὓς μὲν ἡ πόλις νομίζει οὐ νομίζων θεοὺς xen. Sócrates age contra as regras não honrando os deuses que a cidade honra, τούτους πάντες οἱ Σκύθαι νενομίκασι her. a esses [deuses] todos os citas cultuam 3 ταῦτα Ἕλληνες ἀπ’ Αἰγυπτίων νενομίκασι her. esses hábitos os gregos adotaram dos egípcios 4 ὄμμα γὰρ δόμων νομίζω δεσπότου παρουσίαν ésql. pois considero a presença do dono o olho da casa, ἐμὲ ἐκκλησίαν νόμισον καὶ δῆμον plat. considera-me como sendo a assembléia e o povo, καὶ σὺ Ἔρωτα οὐ θεὸν νομίζεις plat. tu também não tens Eros como um deus 5 πάντες νομίζουσι εἶναι θεούς plat. todos crêem que existem deuses, νομιοῦσι σε καὶ αὑτὸν καταδικάζειν σαυτοῦ πάντα τὰ ἔσχατα παθεῖν xen. eles pensarão que tu te condenas a sofrer os mais extremos sofrimentos, ἢ ὡς ἀδελφῷ ἢ ὡς ἀδελφῇ νομίζει ἐντυγχάνειν plat. ele crê reencontrar um irmão ou uma irmã, νόμιζε δ’ ἐὰν ἐμὲ νῦν ἀποκτείνῃς ἄνδρα ἀγαθὸν ἀποκτείνων xen. considera que, se me matas agora, estarás matando um homem de bem 6 ὡς νομίζεται como é o costume, como é hábito, νομιζόμενος consagrado pelo uso, usual, habitual, τὰ νομισθέντα eur., τὰ νομιζόμενα ar. as práticas consagradas pelo uso, ἔχεις παρ’ ἡμῶν οἷά περ νομίζεται ésql. obténs de nós quanto está conforme à lei (ao uso), ἔπειτα δὲ μάντεις τε σφαγία προὔφερον τὰ νομιζόμενα tuc. em seguida, os adivinhos apresentavam as vítimas usuais, ἔξηρχε αὐτὸς ὁ Κῦρος παιᾶνα τὸν νομιζόμενον xen. o próprio Ciro deu início ao peã habitual 7 θανεῖν κακῶν μέγιστον φάρμακον νομίζεται eur. a morte é vista como o maior remédio para os males, οἱ νομιζόμενοι μὲν υἱεῖς, μὴ ὄντες δέ dem. aqueles que passam por filhos, mas não são 8 τίς δ’ ἔσθ’ ὁ χῶρος; τοῦ θεῶν νομίζεται; sóf. que país é este? de que deus o consideram propriedade? οὐ τοῦ κρα­τοῦντος ἡ πόλις νομίζεται; sóf. a cidade não é tida como propriedade do que detém o poder? 〈νόμος〉</p></section></article>\n<article id=\"entry-dgp-28324\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 550 na letra ν · nº geral 28324</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conforme à lei; legal 2 versado no conhecimento da lei; jurisconsulto 3 entre os judeus, doutor da lei 4 crist. devotado à lei mosaica. 〈νόμος〉</p></section></article>\n<article id=\"entry-dgp-28325\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 551 na letra ν · nº geral 28325</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 legalmente; em conformidade com leis 2 crist. em conformidade com a lei mosaica.</p></section></article>\n<article id=\"entry-dgp-28326\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόμιμος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 552 na letra ν · nº geral 28326</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conforme com o uso; habitual 2 conforme com a lei; legal; legítimo; νόμιμόν ἐστι, inf. é justo que 3 que se conforma ao uso, às leis; justo (pessoa) 4 crist. concernente às leis mosaicas ♦ τὸ νόμιμον 5 a lei ou o costume 6 pl. as leis; os usos; os ritos 7 pl. os ritos fúnebres. 〈νόμος〉</p></section></article>\n<article id=\"entry-dgp-28327\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομίμως</h1><div class=\"entry-meta\"><span>DGP · ordem 553 na letra ν · nº geral 28327</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. segundo a lei; de acordo com o uso, com as regras; legalmente.</p></section></article>\n<article id=\"entry-dgp-28328\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόμιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 554 na letra ν · nº geral 28328</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de pastor; pastoril 2 protetor dos rebanhos, epít de deuses. 〈νομή〉</p></section></article>\n<article id=\"entry-dgp-28329\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόμισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 555 na letra ν · nº geral 28329</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 opinião; crença 2 crença religiosa. 〈νομίζω〉</p></section></article>\n<article id=\"entry-dgp-28330\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόμισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 556 na letra ν · nº geral 28330</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 costume; regra; instituição 2 édito; lei 3 moeda em uso; moeda corrente 4 medida padrão (do côngio, do cótilo). 〈νομίζω〉</p></section></article>\n<article id=\"entry-dgp-28331\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομιστέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 557 na letra ν · nº geral 28331</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de νομίζω.</p></section></article>\n<article id=\"entry-dgp-28332\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομιστί</h1><div class=\"entry-meta\"><span>DGP · ordem 558 na letra ν · nº geral 28332</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., tard. 1 segundo a convenção 2 segundo a lei; legalmente. 〈νομίζω〉</p></section></article>\n<article id=\"entry-dgp-28333\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοδείκτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 559 na letra ν · nº geral 28333</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">intérprete das leis; jurisconsulto. 〈νό­μος, διδάσκω〉</p></section></article>\n<article id=\"entry-dgp-28334\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοδιδάκτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 560 na letra ν · nº geral 28334</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mestre em direito; doutor na lei. 〈νόμος, διδάσκω〉</p></section></article>\n<article id=\"entry-dgp-28335\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοδιδάσκαλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 561 na letra ν · nº geral 28335</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = νομοδιδάκτης.</p></section></article>\n<article id=\"entry-dgp-28336\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοθεσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 562 na letra ν · nº geral 28336</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de legislar 2 código de leis; legislação. 〈νομοθέτης〉</p></section></article>\n<article id=\"entry-dgp-28337\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοθετέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 563 na letra ν · nº geral 28337</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. νομοθετήσω, ao. ἐνομοθέτησα, perf. νενομοθέτηκα) 1 criar leis; legislar 2 decidir por lei; estabelecer com lei, ac. ou inf.; νενομοθετημένον ἐστίν, inf. está estabelecido por lei que, a lei estabelece que ♦ méd. 3 instituir leis para si; dar-se leis 4 instituir algo, ac., para si por meio de lei ♦ pas. 5 ser dotado de leis; ter leis 6 ser instituído por meio de lei 7 ser regido por leis. 〈νομοθέτης〉</p></section></article>\n<article id=\"entry-dgp-28338\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοθέτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 564 na letra ν · nº geral 28338</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 legislador 2 pl. os nomotetas, em Atenas, comissão encarregada de rever a legislação. 〈νόμος, τίθημι〉</p></section></article>\n<article id=\"entry-dgp-28339\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοθετέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 565 na letra ν · nº geral 28339</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de νομοθετέω.</p></section></article>\n<article id=\"entry-dgp-28340\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοθετικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 566 na letra ν · nº geral 28340</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de legislação; legislativo 2 especialista em legislação ♦ ἡ νομοθετική 3 arte do legislador. 〈νομοθέτης〉</p></section></article>\n<article id=\"entry-dgp-28341\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομόνδε</h1><div class=\"entry-meta\"><span>DGP · ordem 567 na letra ν · nº geral 28341</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ou νομὸν δέ adv. em direção ao pasto. 〈νόμος, δέ〉</p></section></article>\n<article id=\"entry-dgp-28342\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 568 na letra ν · nº geral 28342</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 província; distrito; região 2 no Egito, nomo 3 na Pérsia, satrapia 4 morada; habitação 5 domínio; campo: ἐπέων πολὺς νομός hom. vasto é o campo das palavras 6 reserva para pasto; pastagem 7 forragem; pasto 8 alimento; comida. 〈νέμω〉</p></section></article>\n<article id=\"entry-dgp-28343\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 569 na letra ν · nº geral 28343</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 uso; costume; hábito; tradição: κατὰ νό­μον her. segundo o costume, γυναικεῖος νόμος ésql. o costume feminino, οἱ κατὰ νόμον ὄντες θεοί plat. os deuses tradicionais 2 costume com força de lei; regra de ação; lei: νόμῳ καὶ δίκῃ át. segundo a lei e o direito, νόμῳ καὶ ἔθει át. segundo a lei e o costume, ν. ἴδιος artt. lei privada, ν. κοινός artt. lei pública, ν. γεγραμμένος artt. lei escrita, ν. κύριος artt. lei em vigor 3 maneira de agir; conduta 4 norma; prescrição; regra de uma arte 5 Mús. modo musical (frígio, lídio, jônio, dórico, eólico) 6 Mús. ária; canto; melodia. 〈νέμω〉</p></section></article>\n<article id=\"entry-dgp-28344\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νομοφύλαξ, ακος (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 570 na letra ν · nº geral 28344</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 masc. guardião das leis, em Atenas, magistrado encarregado de velar pela execução das leis 2 bíbl. observador das leis. 〈νόμος, φύλαξ〉</p></section></article>\n<article id=\"entry-dgp-28345\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόος, νόου,</h1><div class=\"entry-meta\"><span>DGP · ordem 571 na letra ν · nº geral 28345</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. át. νοῦς, νοῦ (ὁ) 1 alma; mente; coração (como sede dos pensamentos, dos sentimentos); τὸν νοῦν ἔχειν ou προσέχειν prestar atenção em alguém, πρός e ac., em algo, dat.; νοῦν ἐχειν át. ter um pensamento ou uma intenção, ἐν νῷ ἔχειν, át. ter em mente, planejar, νῷ ἔχειν ou λαβεῖν compreender 2 disposição da alma; maneira de pensar; sentimento 3 faculdade de pensar; inteligência; razão; pensamento 4 inteligência; sagacidade; prudência; bom-senso; reflexão 5 projeto; intenção; desígnio; resolução 6 significado de palavra, de discurso 1 αἰὲν ἐν στήθεσσι νόον πολυκερδέα νωμῶν hom. mantendo sempre no peito a intenção de obter muitos lucros, ἀγαθῷ νόῳ her. com boa disposição, ἄλλοσ’ ὄμμα, θἠτέρᾳ δὲ νοῦν ἔχειν sóf. ter os olhos voltados para um lado e a atenção para o outro, τούτοις δέομαι ὑμῶν προσέχοντας τὸν νοῦν ἀναμιμῄσκεσθαι and. peço-vos que, prestando atenção nisso, rememoreis os fatos 2 πᾶσι κατὰ νόον ποιεῖν her. agir de acordo com o sentimento de todos, τοῦ στρατηγοῦ ταύτῃ νόος ἔφερε her. a maneira de pensar do general tendia para ela [a pena de morte], οἷον νοσοῦντι ἐξουσίας οὔσης δρᾶν ἃ βούλεται, νοῦν ἰατρικὸν μὴ ἔχοντι plat. como se um doente tivesse liberdade de fazer o que quisesse, sem possuir a disposição de espírito de um médico 3 σὲ χρόνος γέρον θ’ ὁμοῦ τίθησι καὶ τοῦ νοῦ κενόν sóf. o tempo te põe ao mesmo tempo velho e privado da razão, νοῦς ἐστι βασιλεὺς ἡμῖν οὐρανοῦ τε καὶ γῆς plat. para nós o pensamento é rei do céu e da terra 4 οὐδενὶ σὺν νῷ plat. sem nenhuma razão, τοῦ νοῦ κενός sóf. privado de bom-senso, νοῦν ὄλιγον κεκτημένος ar. dotado de pouca inteligência, σμικρὸν νοῦν κεκτῆσθαι plat. ser dotado de pouca inteligência 5 ὅφρα κ’ ἔτι γνῶμεν Τρώων νόον hom. a fim de conhecermos a intenção dos troianos, μεγάλου ∆ιὸς νόος ἐξετελεῖτο hes. cumpria-se o desígnio do grande Zeus 6 οὗτος ὁ νόος τοῦ ῥήματος her. tal é o sentido da palavra, ἦ δὲ παραπλήσιος ὁ νοῦς τῶν ὑπὸ ἑκατέρου παρα­καλουμένων pol. era praticamente o mesmo o significado das exortações que cada um deles fez.</p></section></article>\n<article id=\"entry-dgp-28346\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 572 na letra ν · nº geral 28346</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 doente; doentio 2 de doença; de doente 3 malsão; insalubre. 〈νόσος〉</p></section></article>\n<article id=\"entry-dgp-28347\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 573 na letra ν · nº geral 28347</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐνόσησα, perf. νενόσηκα) 1 (pessoa) estar doente; ter uma doença em uma parte do corpo, ac.: νοσ. ὀφθαλμούς plat. ter os olhos doentes 2 (espírito) estar doente, perturbado 3 (pessoa) ter uma paixão doentia 4 (terra, planta) estar doente; ser afetado por um mal; sofrer de um mal ♦ pas. 5 ser marcado por doença: αἱ ἡμέραι νοσούμεναι hipócr. os dias de doença. 〈νόσος〉</p></section></article>\n<article id=\"entry-dgp-28348\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσηλεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 574 na letra ν · nº geral 28348</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 matéria excretada por doença (líquido, pus) 2 tratamento de uma doença. 〈νοσηλεύω〉</p></section></article>\n<article id=\"entry-dgp-28349\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσηλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 575 na letra ν · nº geral 28349</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medic. 1 cuidar de um doente; curar; οἱ νοση­λεύοντες plut. os médicos ♦ pas. 2 estar doente. 〈νόσος〉</p></section></article>\n<article id=\"entry-dgp-28350\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόσημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 576 na letra ν · nº geral 28350</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 doença 2 sofrimento moral 3 infelicidade; infortúnio 4 flagelo 5 defeito; vício 6 crise; desordem. 〈νόσος〉</p></section></article>\n<article id=\"entry-dgp-28351\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσηματικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 577 na letra ν · nº geral 28351</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">doentio; doente. 〈νόσημα〉</p></section></article>\n<article id=\"entry-dgp-28352\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσημάτιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 578 na letra ν · nº geral 28352</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">doença leve; indisposição. 〈νόσημα〉</p></section></article>\n<article id=\"entry-dgp-28353\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσηρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 579 na letra ν · nº geral 28353</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 malsão; insalubre 2 que faz adoecer; que provoca doença. 〈νόσος〉</p></section></article>\n<article id=\"entry-dgp-28354\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόσος,</h1><div class=\"entry-meta\"><span>DGP · ordem 580 na letra ν · nº geral 28354</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. νοῦσος, ου (ἡ) 1 doença; enfermidade; mal-estar; indisposição; νόσος μεγάλη ou ἱερά o grande mal, a epilepsia 2 esterilidade (da terra) 3 doença moral; sofrimento 4 vício; defeito 5 praga; peste.</p></section></article>\n<article id=\"entry-dgp-28355\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσοτροφία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 581 na letra ν · nº geral 28355</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cuidados com o doente 2 dieta seguida pelo doente. 〈νόσος, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-28356\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσσεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 582 na letra ν · nº geral 28356</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = νεοσσεύω.</p></section></article>\n<article id=\"entry-dgp-28357\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσσιά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 583 na letra ν · nº geral 28357</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = νεοσσιά.</p></section></article>\n<article id=\"entry-dgp-28358\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσσίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 584 na letra ν · nº geral 28358</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = νεοσσίον.</p></section></article>\n<article id=\"entry-dgp-28359\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσσός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 585 na letra ν · nº geral 28359</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">νεοσσός.</p></section></article>\n<article id=\"entry-dgp-28360\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοστέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 586 na letra ν · nº geral 28360</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐνόστησα, perf. νενόστηκα) 1 voltar; retornar 2 ter um retorno feliz 3 passar por algum lugar no caminho de volta ♦ méd. 4 voltar. 〈νόστος〉</p></section></article>\n<article id=\"entry-dgp-28361\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόστιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 587 na letra ν · nº geral 28361</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 relativo ao retorno; do retorno 2 capaz de voltar 3 capaz de dar lucro; produtivo; fértil 4 nutritivo; sustancioso; suculento 5 agradável ao paladar; saboroso ♦ τὸ νόστιμον 6 a melhor parte 7 a parte comestível da fruta. 〈νόστος〉</p></section></article>\n<article id=\"entry-dgp-28362\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόστος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 588 na letra ν · nº geral 28362</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 retorno; viagem de retorno 2 pl. os Retornos, ciclo dos poemas sobre a volta dos combatentes da Guerra de Tróia 3 chegada a um lugar numa viagem de retorno 4 jornada; andança. 〈νέομαι〉</p></section></article>\n<article id=\"entry-dgp-28363\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόσφι</h1><div class=\"entry-meta\"><span>DGP · ordem 589 na letra ν · nº geral 28363</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e νόσφιν adv. 1 ao longe; à parte; νόσφι ἀπό ou ἀπὸ νοσφιν longe de, gen. 2 com exceção de; exceto, gen.</p></section></article>\n<article id=\"entry-dgp-28364\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσφίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 590 na letra ν · nº geral 28364</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. νοσφίσω, át. νοσφιῶ, aor. ἐνόσφισα, perf. desus.) 1 separar; afastar; privar alguém ou algo, ac., de alguém ou de algo, gen. ou ἀπό, ἐκ e gen.: ἐνόσφισάν μ’ Ἡρακλῆος a.r. eles me separaram de Héracles, ἐκ δόμων ἐνόσφισαν θεοί σε eur. os deuses te afastaram de tua morada 2 pôr algo, ac., longe; desviar; tomar; roubar ♦ méd. (aor. ἐνοσφισάμην e ἐνοσφίσθης) 3 privar; espoliar alguém, ac., de, gen.: σφ’ ἀδελφὸς χρημάτων νοσφίζεται eur. seu irmão o priva de seus bens 4 pôr de lado para si; apropriar-se de; roubar 5 afastar-se de, gen. 6 separar-se de; abandonar, ac.: ὅρκον ἐνοσφίσθης a.r. abandonaste o juramento. 〈νόσφι〉</p></section></article>\n<article id=\"entry-dgp-28365\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νόσφιν</h1><div class=\"entry-meta\"><span>DGP · ordem 591 na letra ν · nº geral 28365</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">νόσφι.</p></section></article>\n<article id=\"entry-dgp-28366\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσφισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 592 na letra ν · nº geral 28366</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 usurpação; roubo 2 concussão; peculato 3 exclusão. 〈νοσφίζω〉</p></section></article>\n<article id=\"entry-dgp-28367\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσφισσάμην</h1><div class=\"entry-meta\"><span>DGP · ordem 593 na letra ν · nº geral 28367</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. méd. ép. de νοσφίζω.</p></section></article>\n<article id=\"entry-dgp-28368\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοσώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 594 na letra ν · nº geral 28368</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 doente; enfermo 2 malsão; nocivo 3 funesto; doloroso. 〈νόσος, -ώδης〉</p></section></article>\n<article id=\"entry-dgp-28369\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοτερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 595 na letra ν · nº geral 28369</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 úmido; molhado ♦ τὸ νοτερόν 2 umidade. 〈νότος〉</p></section></article>\n<article id=\"entry-dgp-28370\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 596 na letra ν · nº geral 28370</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 molhar; umedecer 2 estar úmido 3 estar sob a ação do vento sul. 〈νότος〉</p></section></article>\n<article id=\"entry-dgp-28371\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νότιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 597 na letra ν · nº geral 28371</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 que umedece; úmido 2 do sul; meridional ♦ τὸ νότιον 3 mar 4 vento do sul 5 pl. as regiões meridionais. 〈νότος〉</p></section></article>\n<article id=\"entry-dgp-28372\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοτίς, ίδος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 598 na letra ν · nº geral 28372</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 umidade 2 Medic. suor. 〈νότος〉</p></section></article>\n<article id=\"entry-dgp-28373\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νότος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 599 na letra ν · nº geral 28373</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 noto; vento do sul de fortes rajadas 2 região meridional ♦ Νότος 3 Noto, person.</p></section></article>\n<article id=\"entry-dgp-28374\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουθεσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 600 na letra ν · nº geral 28374</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">admoestação; advertência. 〈νουθετέω〉</p></section></article>\n<article id=\"entry-dgp-28375\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουθετέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 601 na letra ν · nº geral 28375</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conduzir à reflexão; lembrar; alertar alguém 2 pôr no pensamento, relembrar, guardar na memória algo 3 admoestar; advertir alguém, ac., de algo, ac. 4 punir; castigar ♦ pas. 5 ser tranqüilizado, acalmado. 〈νοῦς, τίθημι〉</p></section></article>\n<article id=\"entry-dgp-28376\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουθέτημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 602 na letra ν · nº geral 28376</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">advertência; admoestação. 〈νου­θετέω〉</p></section></article>\n<article id=\"entry-dgp-28377\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουθετικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 603 na letra ν · nº geral 28377</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 próprio para advertir, para admoestar ♦ ἡ νουθετική 2 arte de admoestar. 〈νουθετέω〉</p></section></article>\n<article id=\"entry-dgp-28378\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νουμᾶς, ᾶ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 604 na letra ν · nº geral 28378</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Numa, rei de Roma. [lat.]</p></section></article>\n<article id=\"entry-dgp-28379\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουμηνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 605 na letra ν · nº geral 28379</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lua nova 2 primeiro dia do mês 3 em Roma, as calendas. 〈νέος, μήνη〉</p></section></article>\n<article id=\"entry-dgp-28380\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουμήνιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 606 na letra ν · nº geral 28380</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do início do mês; da lua nova ♦ ὁ νουμήνιος 2 espécie de pássaro. 〈νουμηνία〉</p></section></article>\n<article id=\"entry-dgp-28381\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοῦμμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 607 na letra ν · nº geral 28381</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 numo, moeda de três óbolos 2 sestércio, em Roma. [lat.]</p></section></article>\n<article id=\"entry-dgp-28382\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 608 na letra ν · nº geral 28382</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. de νοῦς.</p></section></article>\n<article id=\"entry-dgp-28383\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουνεχής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 609 na letra ν · nº geral 28383</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">racional; sensato; prudente. 〈νοῦς, ἔχω〉</p></section></article>\n<article id=\"entry-dgp-28384\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουνεχόντως</h1><div class=\"entry-meta\"><span>DGP · ordem 610 na letra ν · nº geral 28384</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com sabedoria; com bom senso. 〈νοῦς, ἔχω〉</p></section></article>\n<article id=\"entry-dgp-28385\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νουνεχῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 611 na letra ν · nº geral 28385</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = νουνεχόντως.</p></section></article>\n<article id=\"entry-dgp-28386\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νοῦσος</h1><div class=\"entry-meta\"><span>DGP · ordem 612 na letra ν · nº geral 28386</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = νόσος.</p></section></article>\n<article id=\"entry-dgp-28387\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυγμή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 613 na letra ν · nº geral 28387</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">picada. 〈νύσσω〉</p></section></article>\n<article id=\"entry-dgp-28388\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυγμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 614 na letra ν · nº geral 28388</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">νυγμή.</p></section></article>\n<article id=\"entry-dgp-28389\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτεγερτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 615 na letra ν · nº geral 28389</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">montar guarda à noite. 〈νύξ, ἐγείρω〉</p></section></article>\n<article id=\"entry-dgp-28390\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτέλιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 616 na letra ν · nº geral 28390</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de noite; noturno 2 cultuado à noite, epít. de Dioniso ♦ τὰ νυκτέλια 3 festas noturnas em honra de Dioniso. 〈νύξ, τελέω〉</p></section></article>\n<article id=\"entry-dgp-28391\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτερευτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 617 na letra ν · nº geral 28391</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">próprio para a caça noturna. 〈νυκ­τερεύω〉</p></section></article>\n<article id=\"entry-dgp-28392\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτερεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 618 na letra ν · nº geral 28392</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐνυκτέρευσα) at. e méd. 1 dormir à noite 2 passar a noite em um lugar. 〈νύκτερος〉</p></section></article>\n<article id=\"entry-dgp-28393\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτερινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 619 na letra ν · nº geral 28393</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de noite; noturno. 〈νύξ〉</p></section></article>\n<article id=\"entry-dgp-28394\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτέριος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 620 na letra ν · nº geral 28394</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον = νυκτερινός.</p></section></article>\n<article id=\"entry-dgp-28395\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτερίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 621 na letra ν · nº geral 28395</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 morcego 2 espécie de peixe. 〈νύξ〉</p></section></article>\n<article id=\"entry-dgp-28396\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύκτερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 622 na letra ν · nº geral 28396</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de noite; noturno ♦ νύκτερον adv. 2 à noite. 〈νύξ〉</p></section></article>\n<article id=\"entry-dgp-28397\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτηγορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 623 na letra ν · nº geral 28397</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 realizar uma assembléia à noite ♦ pas. 2 deliberar à noite (um ataque). 〈νύξ, ἀγορά〉</p></section></article>\n<article id=\"entry-dgp-28398\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτηρεφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 624 na letra ν · nº geral 28398</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">oculto pela noite. 〈νύξ, ἐρέφω〉</p></section></article>\n<article id=\"entry-dgp-28399\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτίνομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 625 na letra ν · nº geral 28399</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se alimenta à noite. 〈νύξ, νέμω〉</p></section></article>\n<article id=\"entry-dgp-28400\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτίπλαγκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 626 na letra ν · nº geral 28400</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que faz vagar ou correr à noite 2 que acorda ou mantém acordado à noite 3 que se mantém agitado à noite; que desconhece o sono. 〈νύξ, πλάζω〉</p></section></article>\n";
